CREATE TABLE IF NOT EXISTS s_rdu19(
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
	target int(9) DEFAULT 0,
	result  int(9) DEFAULT 0,
	t10 int(9) DEFAULT 0,
	t11 int(9) DEFAULT 0,
	t12 int(9) DEFAULT 0,
	t01 int(9) DEFAULT 0,
	t02 int(9) DEFAULT 0,
	t03 int(9) DEFAULT 0,
	t04 int(9) DEFAULT 0,
	t05 int(9) DEFAULT 0,
	t06 int(9) DEFAULT 0,
	t07 int(9) DEFAULT 0,
	t08 int(9) DEFAULT 0,
	t09 int(9) DEFAULT 0,
	r10 int(9) DEFAULT 0,
	r11 int(9) DEFAULT 0,
	r12 int(9) DEFAULT 0,
	r01 int(9) DEFAULT 0,
	r02 int(9) DEFAULT 0,
	r03 int(9) DEFAULT 0,
	r04 int(9) DEFAULT 0,
	r05 int(9) DEFAULT 0,
	r06 int(9) DEFAULT 0,
	r07 int(9) DEFAULT 0,
	r08 int(9) DEFAULT 0,
	r09 int(9) DEFAULT 0,
PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_rdu19 WHERE id=@id AND b_year=(@b_year+543);

INSERT IGNORE INTO s_rdu19
(
SELECT
@id,o.hospcode,concat(h.provcode,SUBSTR(CONCAT('00',h.distcode),-2),SUBSTR(CONCAT('00',h.subdistcode),-2),SUBSTR(CONCAT('00',h.mu),-2)) as areacode
,@send,DATE_FORMAT(now(),'%Y%m%d%H%i%s') as d_com,@b_year+543 as b_year
,'0','0'
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI') AND DATE_FORMAT(o.DATE_SERV,'%m') IN(10), CONCAT(o.hospcode,o.pid,o.seq),NULL)) t10
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI') AND DATE_FORMAT(o.DATE_SERV,'%m') IN(11), CONCAT(o.hospcode,o.pid,o.seq),NULL)) t11
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI') AND DATE_FORMAT(o.DATE_SERV,'%m') IN(12), CONCAT(o.hospcode,o.pid,o.seq),NULL)) t12
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI') AND DATE_FORMAT(o.DATE_SERV,'%m') IN(1), CONCAT(o.hospcode,o.pid,o.seq),NULL)) t01
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI') AND DATE_FORMAT(o.DATE_SERV,'%m') IN(2), CONCAT(o.hospcode,o.pid,o.seq),NULL)) t02
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI') AND DATE_FORMAT(o.DATE_SERV,'%m') IN(3), CONCAT(o.hospcode,o.pid,o.seq),NULL)) t03
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI') AND DATE_FORMAT(o.DATE_SERV,'%m') IN(4), CONCAT(o.hospcode,o.pid,o.seq),NULL)) t04
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI') AND DATE_FORMAT(o.DATE_SERV,'%m') IN(5), CONCAT(o.hospcode,o.pid,o.seq),NULL)) t05
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI') AND DATE_FORMAT(o.DATE_SERV,'%m') IN(6), CONCAT(o.hospcode,o.pid,o.seq),NULL)) t06
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI') AND DATE_FORMAT(o.DATE_SERV,'%m') IN(7), CONCAT(o.hospcode,o.pid,o.seq),NULL)) t07
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI') AND DATE_FORMAT(o.DATE_SERV,'%m') IN(8), CONCAT(o.hospcode,o.pid,o.seq),NULL)) t08
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI') AND DATE_FORMAT(o.DATE_SERV,'%m') IN(9), CONCAT(o.hospcode,o.pid,o.seq),NULL)) t09


,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI')  AND DATE_FORMAT(o.DATE_SERV,'%m') IN(10) AND  d.CHK_ANB = 'Y' AND SUBSTR(d.DIDSTD,17,1) IN(1,2,3) AND d.scount IN(1), CONCAT(d.hospcode,d.pid,d.seq),NULL)) r10
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI')  AND DATE_FORMAT(o.DATE_SERV,'%m') IN(11) AND  d.CHK_ANB = 'Y' AND SUBSTR(d.DIDSTD,17,1) IN(1,2,3) AND d.scount IN(1), CONCAT(d.hospcode,d.pid,d.seq),NULL)) r11
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI')  AND DATE_FORMAT(o.DATE_SERV,'%m') IN(12) AND  d.CHK_ANB = 'Y' AND SUBSTR(d.DIDSTD,17,1) IN(1,2,3) AND d.scount IN(1), CONCAT(d.hospcode,d.pid,d.seq),NULL)) r12
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI')  AND DATE_FORMAT(o.DATE_SERV,'%m') IN(1) AND  d.CHK_ANB = 'Y' AND SUBSTR(d.DIDSTD,17,1) IN(1,2,3) AND d.scount IN(1), CONCAT(d.hospcode,d.pid,d.seq),NULL)) r01
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI')  AND DATE_FORMAT(o.DATE_SERV,'%m') IN(2) AND  d.CHK_ANB = 'Y' AND SUBSTR(d.DIDSTD,17,1) IN(1,2,3) AND d.scount IN(1), CONCAT(d.hospcode,d.pid,d.seq),NULL)) r02
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI')  AND DATE_FORMAT(o.DATE_SERV,'%m') IN(3) AND  d.CHK_ANB = 'Y' AND SUBSTR(d.DIDSTD,17,1) IN(1,2,3) AND d.scount IN(1), CONCAT(d.hospcode,d.pid,d.seq),NULL)) r03
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI')  AND DATE_FORMAT(o.DATE_SERV,'%m') IN(4) AND  d.CHK_ANB = 'Y' AND SUBSTR(d.DIDSTD,17,1) IN(1,2,3) AND d.scount IN(1), CONCAT(d.hospcode,d.pid,d.seq),NULL)) r04
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI')  AND DATE_FORMAT(o.DATE_SERV,'%m') IN(5) AND  d.CHK_ANB = 'Y' AND SUBSTR(d.DIDSTD,17,1) IN(1,2,3) AND d.scount IN(1), CONCAT(d.hospcode,d.pid,d.seq),NULL)) r05
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI')  AND DATE_FORMAT(o.DATE_SERV,'%m') IN(6) AND  d.CHK_ANB = 'Y' AND SUBSTR(d.DIDSTD,17,1) IN(1,2,3) AND d.scount IN(1), CONCAT(d.hospcode,d.pid,d.seq),NULL)) r06
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI')  AND DATE_FORMAT(o.DATE_SERV,'%m') IN(7) AND  d.CHK_ANB = 'Y' AND SUBSTR(d.DIDSTD,17,1) IN(1,2,3) AND d.scount IN(1), CONCAT(d.hospcode,d.pid,d.seq),NULL)) r07
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI')  AND DATE_FORMAT(o.DATE_SERV,'%m') IN(8) AND  d.CHK_ANB = 'Y' AND SUBSTR(d.DIDSTD,17,1) IN(1,2,3) AND d.scount IN(1), CONCAT(d.hospcode,d.pid,d.seq),NULL)) r08
,COUNT(DISTINCT IF(GROUP_ASU_PROJECT IN('URI')  AND DATE_FORMAT(o.DATE_SERV,'%m') IN(9) AND  d.CHK_ANB = 'Y' AND SUBSTR(d.DIDSTD,17,1) IN(1,2,3) AND d.scount IN(1), CONCAT(d.hospcode,d.pid,d.seq),NULL)) r09
FROM tmp_diag_asu o  
INNER JOIN chospital h ON o.hospcode=h.hoscode AND h.hostype IN(4,8,9,13,17,18) AND h.provcode IN(@prov_c)
INNER JOIN t_person_db p ON o.hospcode=p.hospcode AND o.PID=p.pid
LEFT JOIN tmp_drug_asu  d  ON o.hospcode=d.HOSPCODE AND o.pid=d.PID AND o.seq=d.SEQ
WHERE o.DATE_SERV BETWEEN @start_d AND @end_d
GROUP BY o.hospcode
);
